handlers.onClick:
{async () => {
                           setSubmitting(true); setActionError('');
                          try { setSelectedRevision(await testCasesApi.getRevision(projectId,caseId,r.id)); }
                           catch (err) { setActionError(err.message); } finally { setSubmitting(false); }
                        }}

handlers.onChange:
{event => {
                    const replacement = event.target.files?.[0];
                    if (!replacement) return;
                    setFiles(previous => previous.map((file, i) => i === index ? replacement : file));
                    update(index, { file: replacement, preview: null, error: '', committed: null });
                  }}
